import sys
import argparse
from toolbox.tasks import find_closest_match, find_closest_match_with_details

def main():
    parser = argparse.ArgumentParser(description="pytoolbox - Internal Python toolbox CLI")
    subparsers = parser.add_subparsers(dest="command")

    # Add the new subcommand
    find_parser = subparsers.add_parser("find-closest-match", help="Find the closest match from a list of names")
    find_parser.add_argument("query", help="The query string to search for")
    find_parser.add_argument("names", nargs="+", help="List of names to search through")
    find_parser.add_argument("--details", action="store_true", help="Show detailed match ratios")
    find_parser.add_argument("--num", type=int, default=3, help="Number of closest matches to return")

    args = parser.parse_args()

    if args.command == "find-closest-match":
        if args.details:
            results = find_closest_match_with_details(args.query, args.names, args.num)
        else:
            results = find_closest_match(args.query, args.names, args.num)

        print("Closest matches:")
        for result in results:
            if args.details:
                print(f"- {result['name']} (ratio: {result['ratio']:.2f})")
            else:
                print(f"- {result}")

    else:
        parser.print_help()
        sys.exit(1)

if __name__ == "__main__":
    main()

