def find_closest_match(query, name_list, threshold=80):
    from fuzzywuzzy import fuzz
    from fuzzywuzzy import process

    # Find the best match
    closest_match = process.extractOne(query, name_list)

    # Optionally filter by a threshold (e.g., only consider matches with > 80% similarity)
    if closest_match and closest_match[1] >= threshold:
        return closest_match[0]
    else:
        return None  # or handle no match case

def find_closest_match(query, name_list, threshold=80):
    from fuzzywuzzy import process

    matches = process.extract(query, name_list, scorer=fuzz.token_sort_ratio)
    best_match = max(matches, key=lambda x: x[1])
    if best_match[1] >= threshold:
        return best_match[0]
    else:
        return None

