class Cache:
    """A cache that stores results with a time-to-live (TTL)."""

    def __init__(self, cache_file='cache.json', ttl=300):  # 5 minutes
        self.cache_file = cache_file
        self.ttl = ttl
        self._load_cache()

    def _load_cache(self):
        """Load the cache from a file."""
        if os.path.exists(self.cache_file):
            with open(self.cache_file, 'r') as f:
                self.cache = json.load(f)
            # Remove expired entries
            self._clean_cache()

    def _save_cache(self):
        """Save the cache to a file."""
        with open(self.cache_file, 'w') as f:
            json.dump(self.cache, f)

    def _clean_cache(self):
        """Remove entries that have expired."""
        current_time = time.time()
        self.cache = {k: v for k, v in self.cache.items() if v['timestamp'] + self.ttl > current_time}

    def _get(self, key):
        """Get a value from the cache."""
        if key in self.cache:
            return self.cache[key]['value']
        return None

    def _set(self, key, value):
        """Set a value in the cache."""
        self.cache[key] = {
            'value': value,
            'timestamp': time.time()
        }
        self._save_cache()

    def get(self, key):
        """Get a value from the cache."""
        return self._get(key)

    def set(self, key, value):
        """Set a value in the cache."""
        return self._set(key, value)

    def __getitem__(self, key):
        return self.get(key)

    def __setitem__(self, key, value):
        self.set(key, value)

    def __contains__(self, key):
        return key in self.cache

    def __len__(self):
        return len(self.cache)

    def clear(self):
        """Clear the entire cache."""
        self.cache = {}
        self._save_cache()

def cached(ttl=300):
    """A decorator that caches the result of a function with a time-to-live (TTL)."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Create a cache instance
            cache = Cache(ttl=ttl)

            # Generate a key based on the function and arguments
            key = f"{func.__qualname__}:{args}{kwargs}"

            # Try to get the value from the cache
            value = cache.get(key)

            if value is not None:
                return value

            # If not in cache, call the function
            result = func(*args, **kwargs)

            # Store the result in the cache
            cache[key] = result

            return result
        return wrapper
    return decorator

import Levenshtein

def find_closest_match(query, name_list, threshold=0.7):
    closest = None
    min_distance = float('inf')

    for name in name_list:
        distance = Levenshtein.distance(query, name)
        ratio = Levenshtein.ratio(query, name)  # ratio is distance / max(len(query), len(name))

        if ratio >= threshold:
            if distance < min_distance:
                min_distance = distance
                closest = name

    return closest

def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    # len(s1) >= len(s2)
    # Create a table to store distances
    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [0] * (len(s2) + 1)
        current_row[0] = i + 1
        for j, c2 in enumerate(s2):
            if c1 == c2:
                current_row[j + 1] = previous_row[j]
            else:
                current_row[j + 1] = 1 + min(
                    previous_row[j],   # deletion
                    current_row[j],    # insertion
                    previous_row[j + 1]  # substitution
                )
        previous_row = current_row
    return previous_row[-1]

def find_closest_match(query, name_list, threshold=0.7):
    closest = None
    min_distance = float('inf')

    for name in name_list:
        distance = levenshtein_distance(query, name)
        ratio = distance / max(len(query), len(name))  # ratio = distance / max(len)

        if ratio >= threshold:
            if distance < min_distance:
                min_distance = distance
                closest = name

    return closest

from functools import lru_cache
import time

def cache_with_ttl(ttl_seconds):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key in cache:
                if time.time() - cache[key]['timestamp'] < ttl_seconds:
                    return cache[key]['value']
                else:
                    del cache[key]
            result = func(*args, **kwargs)
            cache[key] = {'value': result, 'timestamp': time.time()}
            return result
        return wrapper
    return decorator

